using System.Security.Claims;

[AttributeUsage(AttributeTargets.Method)]
public class McpToolAuthorizeAttribute : Attribute
{
    public string RequiredScope { get; }
    public bool RequiresHumanApproval { get; }

    public McpToolAuthorizeAttribute(string requiredScope, bool requiresHumanApproval = false)
    {
        RequiredScope = requiredScope;
        RequiresHumanApproval = requiresHumanApproval;
    }
}

public class McpToolExecutionDispatcher
{
    private readonly IApprovalTokenValidator _approvalValidator;
    private readonly ILogger<McpToolExecutionDispatcher> _logger;

    public McpToolExecutionDispatcher(
        IApprovalTokenValidator approvalValidator,
        ILogger<McpToolExecutionDispatcher> logger)
    {
        _approvalValidator = approvalValidator;
        _logger = logger;
    }

    public async Task<McpToolResult> ExecuteToolAsync(
        string toolName,
        Dictionary<string, object> parameters,
        ClaimsPrincipal caller,
        string? approvalToken,
        CancellationToken ct = default)
    {
        // 1. Resolve tool metadata and security attribute
        var toolMethod = ResolveToolMethod(toolName);
        var authAttr = toolMethod.GetCustomAttribute<McpToolAuthorizeAttribute>();

        if (authAttr != null)
        {
            // 2. Validate caller has required permission scope
            if (!caller.HasClaim("scope", authAttr.RequiredScope))
            {
                _logger.LogWarning("Access denied for user {User} on tool {Tool}", caller.Identity?.Name, toolName);
                return McpToolResult.Fail("Unauthorized: Insufficient tool permission scope.");
            }

            // 3. Enforce Human-in-the-Loop token for dangerous tools
            if (authAttr.RequiresHumanApproval)
            {
                var isValidApproval = await _approvalValidator.ValidateAsync(approvalToken, toolName, parameters, ct);
                if (!isValidApproval)
                {
                    return McpToolResult.RequireHumanApproval(
                        $"Action '{toolName}' requires verified human approval before execution.");
                }
            }
        }

        // 4. Execute validated tool inside sandbox
        return await InvokeUnderIsolationAsync(toolMethod, parameters, ct);
    }
}
